!function(e){function i(i){for(var t,n,o=i[0],m=i[1],c=i[2],s=0,l=[];s<o.length;s++)n=o[s],Object.prototype.hasOwnProperty.call(p,n)&&p[n]&&l.push(p[n][0]),p[n]=0;for(t in m)Object.prototype.hasOwnProperty.call(m,t)&&(e[t]=m[t]);for(d&&d(i);l.length;)l.shift()();return a.push.apply(a,c||[]),r()}function r(){for(var e,i=0;i<a.length;i++){for(var r,n=a[i],o=!0,m=1;m<n.length;m++)r=n[m],0!==p[r]&&(o=!1);o&&(a.splice(i--,1),e=t(t.s=n[0]))}return e}function t(i){if(n[i])return n[i].exports;var r=n[i]={i:i,l:!1,exports:{}};return e[i].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var n={},p={54:0},a=[];t.m=e,t.c=n,t.d=function(e,i,r){t.o(e,i)||Object.defineProperty(e,i,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,i){if(1&i&&(e=t(e)),8&i)return e;if(4&i&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&i&&"string"!=typeof e)for(var n in e)t.d(r,n,function(i){return e[i]}.bind(null,n));return r},t.n=function(e){var i=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(i,"a",i),i},t.o=function(e,i){return Object.prototype.hasOwnProperty.call(e,i)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=i,o=o.slice();for(var c=0;c<o.length;c++)i(o[c]);var d=m;a.push([230,0]),r()}({230:function(e,i,r){"use strict";r.r(i);var t=r(0);Object(t.a)("de","army",r(231),r(1))},231:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轻武器","link":"de_army#de_army_iw"}],"model":"FG42伞兵步枪","description":"<p>FG42是德军为伞兵专门设计的一种自动步枪，它于1942年9月正式定型生产，为FG42/Ⅰ型，由于初期型性能并不理想，后继续进行改进，从中间型过渡到FG42/Ⅱ型。FG42伞兵步枪原设计能进行自动射击，但由于未能解决发射7.92mm步枪弹产生的后座力过大问题，且由于采用全自动射击时容易造成枪管过热，因此实际上只适宜采用半自动射击模式。FG42伞兵步枪可安装光学瞄准镜成为狙击步枪，还可以装上两脚架以保持射击的稳定性，因此有较好的射击精度。在近战时，FG42伞兵步枪还可以装上刺刀进行短兵博斗。总体而言，尽管该枪并不十分完美，但仍是一种成功的能发出压制火力的便携式步枪。</p><p>FG42伞兵步枪产量很少，整个二战期间的总产量只有7000多支，其中有6100多支是1944年11月才定型生产的FG42/Ⅱ。生产出来的FG42伞兵步枪基本上全部装备给德国的伞兵部队，首次亮相是在1943年9月营救意大利独裁者墨索里尼的“橡树”行动中，装备FG42伞兵步枪的德军伞兵乘坐滑翔机空降囚禁墨索里尼的大萨索山峰顶，成功地完成了营救任务。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_iwFG42_11.jpg","description":"<h6>FG42伞兵步枪</h6><p></p><p>技术数据：</p><p>操作：全自动、半自动；</p><p>操作原理：导气式；</p><p>弹药：7.92×57mm毛瑟步枪弹；</p><p>弹匣容量：10发/20发；</p><p>全枪长：940毫米，枪管长：502毫米，重量：4.3公斤；</p><p>射速：900发/每分；</p><p>枪口初速：755米/每秒；</p><p>射程：600米。</p>","caption":"<ol><li>FG42伞兵步枪解剖说明。</li><li>FG42伞兵步枪侧视图。</li><li>装上光学瞄准镜的FG42伞兵步枪。</li><li>安装了两脚支架的FG42伞兵步枪。</li></ol>"}],"part2title":"战场上的FG42伞兵步枪","part2description":"","part2content":[{"image":"imgs/de/army/de_army_iwFG42_21.jpg","description":"（图左）1943年，一名携带FG42伞兵步枪的德军第三伞兵团军士长。（图右）手持FG42伞兵步枪的一名德军伞兵。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_22.jpg","description":"一名持FG42伞兵步枪作坐姿射击状的德军伞兵。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_23.jpg","description":"一名持FG42伞兵步枪作跪姿射击状的德军伞兵。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_24.jpg","description":"绘图：一名持FG42伞兵步枪作站立射击状的德军伞兵。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_25.jpg","description":"1943年9月12日，一支由德军第2伞兵师第7伞兵团和武装党卫军502猎兵团组成的突击队在党卫军特种兵上尉奥托·斯科尔兹内的带领下，乘坐9架滑翔机潜入意大利亚宁平山区的大萨索山帝王台，解救出被囚禁的意大利独裁者墨索里尼，这就是有名的“橡树”行动。图中是一名站在滑翔机前身背FG42伞兵步枪的德军伞兵。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_26.jpg","description":"西线意大利战场，在卡西诺地区作战的德军第1伞兵师的一名伞兵正隐藏在室内持FG42伞兵步枪向进攻的盟军射击，他将FG42伞兵步枪架在一个装手榴弹的箱子上以增强射击稳定性，从挂着的弹链可知该枪弹药很充足，靠窗口处还有一支MP40冲锋枪作备用。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_27.jpg","description":"1943年12月，德国第11伞兵军军长斯图登特伞兵上将到意大利前线的伞兵部队视察，一名陪同的军官向他展示士兵新配备的FG42伞兵步枪。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_28.jpg","description":"西线战场上一名德军伞兵以草丛为掩护，持FG42伞兵步枪聚精会神地注视前方，随时准备投入战斗。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_29.jpg","description":"1944年6月中旬，在西线法国战场诺曼底前线，一名德军伞兵伏在草丛中持FG42伞兵步枪对目标瞄准，准备射击。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_30.jpg","description":"绘图：西线战场，手持着配备光学瞄准镜的FG42伞兵步枪的德军伞兵狙击手，正在向进攻的盟军瞄准射击。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_31.jpg","description":"绘图：1944年西线意大利战场，坚守在“古斯塔夫”防线上的德军第1伞兵师士兵，在卡西诺修道院前方阵地与盟军展开了激烈战斗。战斗中，一名伞兵正在紧张地更换FG42伞兵步枪已打空了的弹夹。","caption":""},{"image":"imgs/de/army/de_army_iwFG42_32.jpg","description":"绘图：战斗在西线战场上的一个德军伞兵小组，一名站立的伞兵正手持FG42伞兵步枪对目标瞄准射击。由于FG42伞兵步枪生产数量太少，德军伞兵部队也只有部分士兵配备了该型自动步枪，其余不少士兵配备的是MP40冲锋枪和98K步枪。","caption":""}]}')}});